--
-- Table structure for `tbl_trusted_devices`
--

DROP TABLE IF EXISTS `tbl_trusted_devices`;
CREATE TABLE `tbl_trusted_devices` (
  `trusted_device_id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `user_id` int(11) NOT NULL,
  `fingerprint_hash` varchar(64) NOT NULL,
  `device_label` varchar(120) DEFAULT NULL,
  `ip_address` varchar(45) DEFAULT NULL,
  `user_agent` text DEFAULT NULL,
  `last_used_at` timestamp NULL DEFAULT NULL,
  `trusted_at` timestamp NULL DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`trusted_device_id`),
  UNIQUE KEY `uq_trusted_device_user_fp` (`user_id`,`fingerprint_hash`),
  KEY `idx_trusted_device_user` (`user_id`)
) ENGINE=InnoDB AUTO_INCREMENT=32 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

