DROP TABLE IF EXISTS `term_import_completions`;
CREATE TABLE `term_import_completions` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `academic_year_id` int(10) unsigned NOT NULL,
  `semester_id` int(10) unsigned NOT NULL,
  `campus_id` int(10) unsigned NOT NULL DEFAULT 0,
  `completed_by` bigint(20) unsigned DEFAULT NULL,
  `completed_at` timestamp NULL DEFAULT NULL,
  `notes` text DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `term_import_completions_ay_sem_campus_unique` (`academic_year_id`,`semester_id`,`campus_id`),
  KEY `term_import_completions_ay_sem_idx` (`academic_year_id`,`semester_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

