--
-- Table structure for `user_session_logs`
--

DROP TABLE IF EXISTS `user_session_logs`;
CREATE TABLE `user_session_logs` (
  `session_log_id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `user_id` int(11) DEFAULT NULL,
  `email` varchar(255) DEFAULT NULL,
  `status` varchar(30) NOT NULL DEFAULT 'success',
  `failure_reason` varchar(255) DEFAULT NULL,
  `ip_address` varchar(45) DEFAULT NULL,
  `user_agent` text DEFAULT NULL,
  `browser` varchar(80) DEFAULT NULL,
  `platform` varchar(80) DEFAULT NULL,
  `device` varchar(80) DEFAULT NULL,
  `token_hash` varchar(64) DEFAULT NULL,
  `login_at` timestamp NULL DEFAULT NULL,
  `logout_at` timestamp NULL DEFAULT NULL,
  `logout_reason` varchar(80) DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`session_log_id`),
  KEY `idx_session_user_login` (`user_id`,`login_at`),
  KEY `idx_session_token_hash` (`token_hash`),
  KEY `idx_session_ip_address` (`ip_address`),
  KEY `idx_session_status` (`status`),
  CONSTRAINT `user_session_logs_user_id_foreign` FOREIGN KEY (`user_id`) REFERENCES `tbl_users` (`user_id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=584 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

